import './ActivityContent.css';

import { Link } from "react-router-dom";
import { timeAgo, formatTimeExpires } from '../lib/DateTimeFormats';
import {ReactComponent as BombIcon} from './svg/bomb.svg';
import ProfileAvatar from './ProfileAvatar';

// Splits a message into plain text, links and #hashtags. split() with a
// capturing group keeps the matches at the odd indexes. Links come first in
// the alternation so a '#' inside a URL stays part of the link. Everything is
// built as React elements, never as an HTML string, so a message cannot
// inject markup (XSS). Hashtags: backlog #41. Links: backlog #46.
const TOKEN_SPLIT = /(https?:\/\/[^\s<>"]+|#[\p{L}\p{N}_]+)/iu;
const LINK_START = /^https?:\/\//i;
const TRAILING_PUNCT = /[.,!?;:'"]$/;
const LINK_DISPLAY_MAX = 40;

// "see https://example.com." -> the period is sentence punctuation, not part
// of the link. A closing ")" is trimmed only when it has no matching "(",
// so Wikipedia-style links such as /wiki/Foo_(bar) stay whole.
function splitTrailing(raw) {
  let url = raw;
  let trail = '';
  for (;;) {
    const last = url.slice(-1);
    const unbalanced = last === ')' &&
      url.split(')').length > url.split('(').length;
    if (TRAILING_PUNCT.test(url) || unbalanced) {
      trail = last + trail;
      url = url.slice(0, -1);
    } else {
      return [url, trail];
    }
  }
}

function renderLink(raw, key) {
  const [url, trail] = splitTrailing(raw);
  let href = null;
  try {
    const parsed = new URL(url);
    // Only web links become clickable; anything else stays plain text.
    if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
      href = parsed.href;
    }
  } catch (e) {
    href = null;
  }
  if (!href) {
    return raw;
  }
  const bare = Array.from(url.replace(LINK_START, ''));
  const display = bare.length > LINK_DISPLAY_MAX
    ? bare.slice(0, LINK_DISPLAY_MAX).join('') + '\u2026'
    : bare.join('');
  return (
    <span key={key}>
      <a
        className='link'
        href={href}
        title={url}
        target='_blank'
        rel='noopener noreferrer nofollow'
        onClick={(e) => e.stopPropagation()}
      >{display}</a>{trail}
    </span>
  );
}

function renderMessage(message) {
  if (typeof message !== 'string' || message === '') {
    return message;
  }
  return message.split(TOKEN_SPLIT).map((part, i) => {
    if (i % 2 === 0) {
      return part;
    }
    if (LINK_START.test(part)) {
      return renderLink(part, i);
    }
    return <span className='hashtag' key={i}>{part}</span>;
  });
}

export default function ActivityContent(props) {

  // formatTimeExpires returns null once the post has expired; the countdown
  // is then hidden rather than shown as negative minutes (backlog #25).
  let expires_at;
  const expires_label = props.activity.expires_at
    ? formatTimeExpires(props.activity.expires_at)
    : null;
  if (expires_label) {
    expires_at =  <div className="expires_at" title={props.activity.expires_at}>
                    <BombIcon className='icon' />
                    <span className='ago'>{expires_label}</span>
                  </div>

  }

  return (
    <div className='activity_content_wrap'>
      <div className='activity_avatar'>
  <ProfileAvatar id={props.activity.cognito_user_id} name={props.activity.display_name} />
</div>
      <div className='activity_content'>
        <div className='activity_meta'>
          <Link className='activity_identity' to={`/@`+props.activity.handle}>
            <div className='display_name'>{props.activity.display_name}</div>
            <div className="handle">@{props.activity.handle}</div>
          </Link>{/* activity_identity */}
          <div className='activity_times'>
            <div className="created_at" title={props.activity.created_at}>
              <span className='ago'>{timeAgo(props.activity.created_at)}</span> 
            </div>
            {expires_at}
          </div>{/* activity_times */}
        </div>{/* activity_meta */}
        <div className="message">{renderMessage(props.activity.message)}</div>
      </div>{/* activity_content */}
    </div>
  );
}

.activity_content_wrap {
  display: flex;
  flex-direction: row;
  align-items: start;
}

.activity_content {
  flex-grow: 1;
  padding-left: 12px;
}

.activity_content_wrap .activity_avatar {
  background: rgb(149,0,255);
  height: 60px;
  width: 60px;
  border-radius: 999px;
  flex-shrink: 0;
}

.activity_content .activity_meta {
  display: flex;
  justify-content: space-between;
}

.activity_content a.activity_identity {
  flex-grow: 1;
  text-decoration: none;
  font-size: 16px;
}

.activity_content a.activity_identity .display_name {
  font-weight: 800;
  color: #fff;
}

.activity_content  a.activity_identity .handle {
  color: rgb(255,255,255,0.5);
}

.activity_content .activity_times {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.activity_content .activity_times .created_at {
  color: rgb(72,77,95);
  font-size: 14px;
}

.activity_content .activity_times .expires_at {
  color: rgb(149,0,255);
  font-size: 14px;
  display: flex;
  gap: 2px;
}
.activity_content .activity_times .expires_at svg.icon {
  fill: rgb(149,0,255);
  width: 14px;
  height: 14px;
}

.activity_content .message {
  color: #fff;
  font-size: 16px;
  margin-top: 8px;
}
.activity_avatar img {
  width: 60px;
  height: 60px;
  border-radius: 999px;
  object-fit: cover;
}

/* #hashtags inside a message (backlog #41). Theme purple; semi-bold because
   this purple is only 3.7:1 against the black background. */
.activity_content .message .hashtag {
  color: rgb(149,0,255);
  font-weight: 600;
}

/* Links inside a message (backlog #46). Lighter purple than the hashtags so
   they pass contrast on black (6.2:1); underline marks them as clickable.
   overflow-wrap lets a long link wrap instead of widening the column. */
.activity_content .message a.link {
  color: rgb(176,102,255);
  text-decoration: underline;
  overflow-wrap: anywhere;
}
.activity_content .message a.link:hover {
  color: #fff;
}

import './ProfileAvatar.css';
import { useState } from 'react';

// One cache key per page load. Date.now() inside render produced a new URL
// on every re-render, so the browser re-downloaded every avatar each time
// (the (canceled) jpg rows in DevTools). A new upload shows after a reload.
const AVATAR_VERSION = Date.now();

// Real ids are Cognito subs (UUIDs). Seed rows such as 'MOCK' have no photo,
// so requesting one only produced a 403 in DevTools (backlog #34).
const COGNITO_SUB = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export default function ProfileAvatar({ id, name }) {
  // Fall back to an initial when there is no real id to build a URL from,
  // or when the image fails to load because the user never uploaded one.
  const [failed, setFailed] = useState(false);
  const initial = (name || '?').trim().charAt(0).toUpperCase() || '?';

  if (!id || !COGNITO_SUB.test(id) || failed) {
    return (
      <div className='profile-avatar'>
        <div className='avatar-fallback' aria-label='User avatar'>{initial}</div>
      </div>
    );
  }

  return (
    <div className='profile-avatar'>
      <img
        src={`https://assets.fentoncruddur.com/avatars/processed/${id}.jpg?v=${AVATAR_VERSION}`}
        className='avatar-img'
        alt='User avatar'
        onError={() => setFailed(true)}
      />
    </div>
  );
}

import './ActivityFeed.css';
import ActivityItem from './ActivityItem';

// props.banner ('home' | 'notifications') adds a page banner and makes the
// heading sticky (banner CSS in ActivityFeed.css). Without it the heading is
// unchanged, so the Profile page (no title, no banner) looks the same as before.
// props.children (e.g. the Home compose form) renders BELOW the heading, so an
// open form no longer pushes the sticky banner down (backlog #45).
export default function ActivityFeed(props) {
  const headingClass = props.banner
    ? `activity_feed_heading banner banner_${props.banner}`
    : 'activity_feed_heading';
  return (
    <div className='activity_feed'>
      <div className={headingClass}>
        <div className='title'>{props.title}</div>
      </div>
      {props.children}
      <div className='activity_feed_collection'>
        {props.activities.map(activity => {
        return  <ActivityItem setReplyActivity={props.setReplyActivity} setPopped={props.setPopped} key={activity.uuid} activity={activity} />
        })}
      </div>
    </div>
  );
}

import './HomeFeedPage.css';
import React from "react";
import { useLocation, useNavigate } from 'react-router-dom';

import DesktopNavigation  from '../components/DesktopNavigation';
import DesktopSidebar     from '../components/DesktopSidebar';
import ActivityFeed from '../components/ActivityFeed';
import ActivityForm from '../components/ActivityForm';
import ReplyForm from '../components/ReplyForm';        

import { signOut } from 'aws-amplify/auth';
import { checkAuth, getAccessToken } from '../components/lib/CheckAuth';

export default function HomeFeedPage() {
  const [activities, setActivities] = React.useState([]);
  const [popped, setPopped] = React.useState(false);
  const [poppedReply, setPoppedReply] = React.useState(false);
  const [replyActivity, setReplyActivity] = React.useState({});
  const [user, setUser] = React.useState(null);
  const location = useLocation();
  const navigate = useNavigate();

const loadData = async () => {
    console.log('loadData called');
    const headers = {};

    // Get a fresh access token (auto-refreshes if expired)
    const accessToken = await getAccessToken();
    if (accessToken) {
      headers['Authorization'] = `Bearer ${accessToken}`;
    }

    const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/activities/home`;

    try {
      const res = await fetch(backend_url, {
        method: "GET",
        headers: headers,
      });

      const resJson = await res.json();
      if (res.status === 200) {
        setActivities(resJson)
      } else {
        console.log(res);
      }
    } catch (err) {
      console.log(err);
    }
  };

  const handleSignOut = async () => {
    try {
      await signOut();
      window.location.href = "/";
    } catch (error) {
      console.log('Error signing out: ', error);
    }
  };

  React.useEffect(() => {
    // This useEffect will run once when the component is mounted
    // to check the user's authentication status and then load data
    checkAuth(setUser);
    loadData();
  }, []);

  // The Crud button on any other page navigates here with { compose: true }
  // (backlog #40). Open the form, then clear the flag with a replace so a
  // refresh or Back does not reopen it.
  React.useEffect(() => {
    if (location.state && location.state.compose) {
      setPopped(true);
      navigate(location.pathname, { replace: true, state: {} });
    }
  }, [location.state, location.pathname, navigate]);

  React.useEffect(() => {
    // This effect runs whenever the `user` state changes
    // It will trigger loadData only after a user is authenticated
    if (user) {
      loadData(user);
    }
  }, [user]);

  return (
    <article>
      <DesktopNavigation user={user} active={'home'} setPopped={setPopped} handleSignOut={handleSignOut} />
      <div className='content'>
        <ReplyForm 
          activity={replyActivity} 
          popped={poppedReply} 
          setPopped={setPoppedReply} 
          setActivities={setActivities} 
          activities={activities} 
        />
        <ActivityFeed 
          title="Home" 
          banner="home" 
          setReplyActivity={setReplyActivity} 
          setPopped={setPoppedReply} 
          activities={activities} 
        >
          {/* Compose form renders below the sticky Home banner (backlog #45). */}
          <ActivityForm
            popped={popped}
            setPopped={setPopped}
            setActivities={setActivities}
          />
        </ActivityFeed>
      </div>
      <DesktopSidebar user={user} />
    </article>
  );
}
